const containers = $input.first().json;

const healthy = [];
const unhealthy = [];
const stopped = [];
const noHealthcheck = [];

for (const c of containers) {
  const name = (c.Names && c.Names[0]) ? c.Names[0].replace('/', '') : 'unknown';
  const state = (c.State || '').toLowerCase();
  const status = (c.Status || '').toLowerCase();

  if (state !== 'running') {
    stopped.push(name);
  } else if (status.includes('(healthy)')) {
    healthy.push(name);
  } else if (status.includes('(unhealthy)')) {
    unhealthy.push(name);
  } else if (status.includes('(health:')) {
    unhealthy.push(name + ' (starting)');
  } else {
    noHealthcheck.push(name);
  }
}

const total = containers.length;
const issues = unhealthy.concat(stopped);
const hasIssues = issues.length > 0;

const summaryForGemini = `Docker container health report:\n- Total containers: ${total}\n- Healthy: ${healthy.length} (${healthy.join(', ')})\n- Unhealthy: ${unhealthy.length} (${unhealthy.join(', ') || 'none'})\n- Stopped: ${stopped.length} (${stopped.join(', ') || 'none'})\n- No healthcheck: ${noHealthcheck.length} (${noHealthcheck.join(', ') || 'none'})\n\nProvide a 2-3 sentence analysis. If all healthy, confirm all good. If issues exist, identify what might be wrong and suggest action. Be concise, plain text.`;

return [{ json: { summaryForGemini, healthy, unhealthy, stopped, noHealthcheck, total, hasIssues } }];

const gemRes = $input.first().json;
const prev = $('Analyze Container States').first().json;

let analysis = '';
try {
  analysis = gemRes.candidates[0].content.parts[0].text.trim();
} catch(e) {}

const date = new Date().toISOString().split('T')[0];
const statusIcon = prev.hasIssues ? '\u26a0\ufe0f' : '\u2705';

let msg = `${statusIcon} CRYPTEX Daily Health — ${date}\n\n`;
msg += `\ud83d\udce6 ${prev.total} containers total\n`;
msg += `\u2705 Healthy: ${prev.healthy.length}\n`;

if (prev.unhealthy.length > 0) {
  msg += `\u274c Unhealthy: ${prev.unhealthy.join(', ')}\n`;
}
if (prev.stopped.length > 0) {
  msg += `\u23f9\ufe0f Stopped: ${prev.stopped.join(', ')}\n`;
}
if (prev.noHealthcheck.length > 0) {
  msg += `\u2796 No healthcheck: ${prev.noHealthcheck.join(', ')}\n`;
}

if (analysis) {
  msg += `\n\ud83e\udd16 ${analysis}`;
}

return [{ json: { message: msg } }];
